using System.Security.Claims;
using System.Text.Json;
using Holonix.Server.Application.Services;
using Holonix.Server.Contracts.Business;
using Holonix.Server.Controllers;
using Holonix.Server.Domain.Entities;
using Holonix.Server.Infrastructure.Data;
using Holonix.Server.Infrastructure.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging.Abstractions;
using Xunit;
namespace Holonix.Server.Tests;

public sealed class BusinessJobsTests
{
    private static JsonElement Json(IActionResult result) => JsonSerializer.SerializeToElement(Assert.IsType<OkObjectResult>(result).Value, new JsonSerializerOptions(JsonSerializerDefaults.Web));
    private static ControllerContext Context(string id) => new() { HttpContext = new DefaultHttpContext { User = new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier, id)], "test")) } };
    [Fact]
    public async Task Jobs_UseFullData_EnforceLifecycleTeamAndFinancialPermissions()
    {
        await using var db = new ApplicationDbContextFactory().CreateDbContext([]);
        await using var transaction = await db.Database.BeginTransactionAsync();
        var manualType = await db.WorkloadTypes.SingleOrDefaultAsync(t => t.Type == "Manual Job");
        if (manualType == null) { manualType = new WorkloadType { Type = "Manual Job" }; db.Add(manualType); await db.SaveChangesAsync(); }
        foreach (var name in new[] { "Scheduled", "Ready To Start", "In Progress", "Completed", "Cancelled" })
            if (!await db.WorkloadStatuses.AnyAsync(s => s.WorkloadTypeId == manualType.WorkloadTypeId && s.Status == name)) db.Add(new WorkloadStatus { WorkloadTypeId = manualType.WorkloadTypeId, Status = name });
        var business = new Business { BusinessCode = Guid.NewGuid().ToString("N")[..10].ToUpperInvariant(), Name = "Jobs rollback fixture", StartDate = new DateOnly(2026,1,1) };
        var owner = new ApplicationUser { Id = Guid.NewGuid().ToString(), FirstName = "Jobs", LastName = "Owner" };
        var employee = new ApplicationUser { Id = Guid.NewGuid().ToString(), FirstName = "Jobs", LastName = "Employee" };
        var other = new ApplicationUser { Id = Guid.NewGuid().ToString(), FirstName = "Jobs", LastName = "Other" };
        db.AddRange(business,owner,employee,other); await db.SaveChangesAsync();
        var members = new[] { owner,employee,other }.Select(u => new BusinessUser { BusinessId = business.BusinessId, UserId = u.Id, IsActive = true, StartDate = DateTime.UtcNow.AddDays(-2) }).ToArray();
        db.AddRange(members); await db.SaveChangesAsync();
        var ownerRole = await db.BusinessRoles.SingleAsync(r=>r.Name=="Owner");
        var employeeRole = await db.BusinessRoles.SingleAsync(r=>r.Name=="Employee");
        for(var i=0;i<members.Length;i++) db.Add(new BusinessUserRole { BusinessUserId = members[i].BusinessUserId, BusinessRoleId = i==0?ownerRole.BusinessRoleId:employeeRole.BusinessRoleId, StartDate = DateTime.UtcNow.AddDays(-2) });
        for(byte day=0;day<7;day++) foreach(var member in members) db.Add(new BusinessUserAvailability { BusinessUserId=member.BusinessUserId, DayOfWeek=day, StartTime=new TimeOnly(8,0), EndTime=new TimeOnly(18,0), EffectiveStartDate=new DateOnly(2026,1,1) });
        var past = DateTime.UtcNow.Date.AddDays(-1).AddHours(9);
        var future = DateTime.UtcNow.Date.AddDays(2).AddHours(9);
        var work = new Job { BusinessId = business.BusinessId, Name="Legacy work", StartDateTime=past,EndDateTime=past.AddHours(1),Cost=75,NetCost=70,BusinessUserId=members[1].BusinessUserId };
        var change = new Job { BusinessId = business.BusinessId, Name="Future work", StartDateTime=future,EndDateTime=future.AddHours(1),Cost=50,NetCost=45 };
        var conflict = new Job { BusinessId = business.BusinessId, Name="Conflicting legacy work", StartDateTime=future,EndDateTime=future.AddHours(2),BusinessUserId=members[1].BusinessUserId };
        db.AddRange(work,change,conflict);
        for(var i=0;i<30;i++) db.Add(new Job { BusinessId=business.BusinessId,Name="Page job "+i,StartDateTime=future.AddDays(i+4),EndDateTime=future.AddDays(i+4).AddHours(1),Cost=10,NetCost=8 });
        await db.SaveChangesAsync();
        var validator = new JobTeamValidator(db,new BusinessAvailabilityCalculator());
        var controller = new BusinessJobsController(db,validator) { ControllerContext=Context(owner.Id) };
        var list = Json(await controller.List(business.BusinessCode,new JobsQuery { PageSize=10 },default));
        Assert.Equal(33,list.GetProperty("total").GetInt32()); Assert.Equal(10,list.GetProperty("jobs").GetArrayLength());
        Assert.Equal(0,list.GetProperty("summary").GetProperty("inProgress").GetInt32());
        Assert.Equal(425,list.GetProperty("summary").GetProperty("totalValue").GetDecimal());
        var second = Json(await controller.List(business.BusinessCode,new JobsQuery {Page=2,PageSize=10},default)); Assert.Equal(10,second.GetProperty("jobs").GetArrayLength());
        var search = Json(await controller.List(business.BusinessCode,new JobsQuery { Search="Jobs Employee" },default)); Assert.Equal(2,search.GetProperty("total").GetInt32());
        var invalidComplete=Assert.IsType<ObjectResult>(await controller.Complete(business.BusinessCode,work.JobId,new JobCommand(),default)); Assert.Equal(409,invalidComplete.StatusCode);
        controller.ControllerContext=Context(other.Id);
        Assert.Equal(403,Assert.IsType<ObjectResult>(await controller.Ready(business.BusinessCode,work.JobId,new JobCommand(),default)).StatusCode);
        controller.ControllerContext=Context(employee.Id);
        var employeeList = Json(await controller.List(business.BusinessCode,new JobsQuery(),default)); Assert.Equal(JsonValueKind.Null,employeeList.GetProperty("summary").GetProperty("totalValue").ValueKind);
        Assert.All(employeeList.GetProperty("jobs").EnumerateArray(),j=>Assert.Equal(JsonValueKind.Null,j.GetProperty("cost").ValueKind));
        Assert.IsType<OkObjectResult>(await controller.Ready(business.BusinessCode,work.JobId,new JobCommand(),default));
        Assert.IsType<OkObjectResult>(await controller.Start(business.BusinessCode,work.JobId,new JobCommand(),default));
        Assert.IsType<OkObjectResult>(await controller.Complete(business.BusinessCode,work.JobId,new JobCommand(),default));
        Assert.NotNull(work.CompletedDateTime); Assert.Equal(employee.Id,work.CompletedByUserId);
        controller.ControllerContext=Context(owner.Id);
        Assert.Equal(400,Assert.IsType<ObjectResult>(await controller.Reassign(business.BusinessCode,work.JobId,new JobTeamCommand([members[0].BusinessUserId]),default)).StatusCode);
        var choices=Assert.IsAssignableFrom<IReadOnlyList<JobEmployeeOption>>(Assert.IsType<OkObjectResult>(await controller.TeamOptions(business.BusinessCode,change.JobId,default)).Value);
        Assert.False(choices.Single(o=>o.BusinessUserId==members[1].BusinessUserId).CanAssign);
        Assert.Equal(400,Assert.IsType<ObjectResult>(await controller.Reassign(business.BusinessCode,change.JobId,new JobTeamCommand([members[1].BusinessUserId]),default)).StatusCode);
        var original=Assert.IsType<OperationalJob>(Assert.IsType<OkObjectResult>(await controller.Detail(business.BusinessCode,change.JobId,default)).Value);
        Assert.IsType<OkObjectResult>(await controller.Reassign(business.BusinessCode,change.JobId,new JobTeamCommand([members[0].BusinessUserId],original.Revision),default));
        Assert.Equal(409,Assert.IsType<ObjectResult>(await controller.Reassign(business.BusinessCode,change.JobId,new JobTeamCommand([],original.Revision),default)).StatusCode);
        Assert.IsType<OkObjectResult>(await controller.Reassign(business.BusinessCode,change.JobId,new JobTeamCommand([]),default)); Assert.Null(change.BusinessUserId);
        Assert.IsType<OkObjectResult>(await controller.Cancel(business.BusinessCode,change.JobId,new JobCommand(),default));
        Assert.Equal(409,Assert.IsType<ObjectResult>(await controller.Complete(business.BusinessCode,change.JobId,new JobCommand(),default)).StatusCode);
        var bookingType=await db.WorkloadTypes.SingleAsync(t=>t.Type=="Customer Booking");
        var pendingStatus=await db.WorkloadStatuses.SingleAsync(s=>s.WorkloadTypeId==bookingType.WorkloadTypeId&&s.Status=="Awaiting Acceptance");
        var pending = new Job { BusinessId=business.BusinessId,Name="Pending",StartDateTime=future,EndDateTime=future.AddHours(1),Cost=900 };
        var workload = new Workload { WorkloadTypeId=bookingType.WorkloadTypeId,WorkloadStatusId=pendingStatus.WorkloadStatusId,CreatedByUserId=owner.Id,CreatedDate=DateTime.UtcNow };
        db.Add(new JobWorkload {Job=pending,Workload=workload}); await db.SaveChangesAsync();
        Assert.Equal(404,Assert.IsType<ObjectResult>(await controller.Complete(business.BusinessCode,pending.JobId,new JobCommand(),default)).StatusCode);
        var completeFilter=Json(await controller.List(business.BusinessCode,new JobsQuery {Filter="completed"},default)); Assert.Equal(1,completeFilter.GetProperty("total").GetInt32());
        var category = await db.Services.Select(s=>s.ServiceId).FirstAsync();
        var service = new BusinessSubService { BusinessId=business.BusinessId, ServiceId=category, Name="Manual service", Price=40, DurationMinutes=30, EmployeeCount=1, EffectiveDate=new DateOnly(2026,1,1) };
        db.Add(service);await db.SaveChangesAsync();
        db.Add(new BusinessSubServiceAssignment {BusinessSubServiceId=service.BusinessSubServiceId,BusinessUserId=members[0].BusinessUserId});await db.SaveChangesAsync();
        var manualOptions = Assert.IsType<JobOptions>(Assert.IsType<OkObjectResult>(await controller.Options(business.BusinessCode,default)).Value);
        Assert.Contains(manualOptions.Services,option=>option.BusinessSubServiceId==service.BusinessSubServiceId);
        var created = Json(await controller.Create(business.BusinessCode,new CreateManualJobRequest {Name="Created job",StartDateTime=future.AddDays(60),EndDateTime=future.AddDays(60).AddHours(1),BusinessSubServiceIds=[service.BusinessSubServiceId],BusinessUserIds=[members[0].BusinessUserId]},default));
        var createdId=created.GetProperty("jobId").GetInt64();
        var createdJob=Assert.IsType<OperationalJob>(Assert.IsType<OkObjectResult>(await controller.Detail(business.BusinessCode,createdId,default)).Value);
        Assert.Equal(40,createdJob.Cost);Assert.Single(createdJob.Services);Assert.Single(createdJob.AssignedEmployees);
        Assert.IsType<OkObjectResult>(await controller.Reschedule(business.BusinessCode,createdId,new JobScheduleCommand(future.AddDays(60).AddHours(1),future.AddDays(60).AddHours(2),createdJob.Revision),default));
        Assert.Equal(400,Assert.IsType<ObjectResult>(await controller.Reassign(business.BusinessCode,createdId,new JobTeamCommand([members[2].BusinessUserId]),default)).StatusCode);
        service.RequiresServiceLocation=true;await db.SaveChangesAsync();
        var locationRequest=new CreateManualJobRequest {Name="Location job",StartDateTime=future.AddDays(62),EndDateTime=future.AddDays(62).AddHours(1),BusinessSubServiceIds=[service.BusinessSubServiceId]};
        Assert.Equal(400,Assert.IsType<ObjectResult>(await controller.Create(business.BusinessCode,locationRequest,default)).StatusCode);
        locationRequest.ServiceLocation=new ManualJobLocation {Address1="1 Fixture Street",City="Fixture",State="GA",ZipCode="30000"};
        var locationCreated=Json(await controller.Create(business.BusinessCode,locationRequest,default));
        var locationDetail=Assert.IsType<OperationalJob>(Assert.IsType<OkObjectResult>(await controller.Detail(business.BusinessCode,locationCreated.GetProperty("jobId").GetInt64(),default)).Value);
        Assert.Equal("1 Fixture Street",locationDetail.ServiceLocation?.Address1);
        var createdLink=await db.JobWorkloads.SingleAsync(w=>w.JobId==createdId);
        db.Add(new BookingPayment {JobId=createdId,WorkloadId=createdLink.WorkloadId,PaymentStatus="Charge Succeeded",CreatedDate=DateTime.UtcNow,UpdatedDate=DateTime.UtcNow});await db.SaveChangesAsync();
        Assert.Equal(400,Assert.IsType<ObjectResult>(await controller.Cancel(business.BusinessCode,createdId,new JobCommand(),default)).StatusCode);
        var inactiveJob=new Job {BusinessId=business.BusinessId,Name="Inactive assigned job",StartDateTime=future.AddDays(63),EndDateTime=future.AddDays(63).AddHours(1),BusinessUserId=members[2].BusinessUserId};
        members[2].IsActive=false;db.Add(inactiveJob);await db.SaveChangesAsync();
        var inactiveOptions=Assert.IsAssignableFrom<IReadOnlyList<JobEmployeeOption>>(Assert.IsType<OkObjectResult>(await controller.TeamOptions(business.BusinessCode,inactiveJob.JobId,default)).Value);
        Assert.False(inactiveOptions.Single(o=>o.BusinessUserId==members[2].BusinessUserId).CanAssign);
        Assert.IsType<OkObjectResult>(await controller.Reassign(business.BusinessCode,inactiveJob.JobId,new JobTeamCommand([]),default));
        var overnight=new Job {BusinessId=business.BusinessId,StartDateTime=future.Date.AddHours(17),EndDateTime=future.Date.AddDays(1).AddHours(9)};
        Assert.All(await validator.Options(business.BusinessId,overnight,default),option=>Assert.False(option.CanAssign));
        var workspaceController = new BusinessController(db,null!,null!,null!,new BusinessAvailabilityCalculator(),null!,NullLogger<BusinessController>.Instance) {ControllerContext=Context(employee.Id)};
        var workspace=Assert.IsType<BusinessWorkspaceResponse>(Assert.IsType<OkObjectResult>(await workspaceController.GetBusinessWorkspace(business.BusinessCode,default)).Value);
        Assert.Null(workspace.TotalRevenue); Assert.All(workspace.Jobs,j=>{ Assert.Null(j.Cost); Assert.Null(j.NetCost); }); Assert.All(workspace.JobRequests,j=>Assert.Null(j.Cost));
        workspaceController.ControllerContext=Context(owner.Id);
        Assert.IsType<BadRequestObjectResult>(await workspaceController.AcceptJobRequest(business.BusinessCode,workload.WorkloadId,new AcceptJobRequestRequest([members[1].BusinessUserId]),default));
        Assert.Equal(pendingStatus.WorkloadStatusId,workload.WorkloadStatusId);
        controller.ControllerContext=Context(other.Id);
        Assert.Equal(403,Assert.IsType<ObjectResult>(await controller.List("XXXXXXXXXX",new JobsQuery(),default)).StatusCode);
        await transaction.RollbackAsync();
    }
}
